insert into negocios (id, nombre, slug, categoria_oficial_id, municipio, vereda_id, direccion, latitud, longitud, descripcion_corta, descripcion, producto, telefono, whatsapp, email, representante_legal, nit, naturaleza_juridica, delegado, rut_camara_comercio, responsable_cdmb, novedad, tipo_negocio_verde, anio_registro, cota_msnm, este, norte, aplicacion_ficha_2025, observaciones, registro_nacional_turismo, uso_suelo, concesion_aguas, concesion_aguas_vencimiento, vertimientos, vertimientos_vencimiento, pueaa, pgris, pozo_septico, alcantarillado, ica, ica_vencimiento, invima, invima_vencimiento, certificado_tenencia_animales, buenas_practicas_agricolas, buenas_practicas_apicolas, registro_apicola, intervencion_cauce, capacidad_carga, sstt, canal_venta, exportacion, huella_carbono, fortalezas_ambiental, fortalezas_social, fortalezas_economico, emprendimiento_verde, sello_marca, avalado, destacado, activo) values ('18c1e5a7-5d87-47da-a3b0-a70bd631e36c', 'ASOSANTURBAN', generar_slug_unico('ASOSANTURBAN', '18c1e5a7-5d87-47da-a3b0-a70bd631e36c'), (select id from categorias_oficiales where slug = 'pendiente-clasificar'), 'Suratá', (select id from veredas where municipio = 'Suratá' and slug = 'capilla-alta'), 'Vereda Gramalotico, Suratá', 7.1113888888888885, -73.10555555555555, 'Genera un impacto ambiental positivo al incentivar en el núcleo de productores prácticas de agricultura resiliente y responsable con el ambiente,…', 'Genera un impacto ambiental positivo al incentivar en el núcleo de productores prácticas de agricultura resiliente y responsable con el ambiente, minimizando el uso de agroquímicos, promoviendo los procesos biológicos/ecológicos en el proceso productivo, disminuyendo la presión sobre el suelo, agua y aire. Sus buenas prácticas generan beneficios multiplicadores al tratarse de una organización que agrupa 25 familias rurales y quienes habitan un entorno natural con riqueza hídrica, en flora y fauna.', 'PITAYA', '3177942070', '573177942070', 'asosanturban@gmail.com', 'HECTOR ADOLFO PRADA CHAVEZ', '900794808-5', null, null, null, 'ALEXANDRA SOTOMONTE', 'RETIRADO', 'Inicial', 2021, null, '73°6''20''''', '7°6''41''''', null, 'Continua en el programa', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, true, false, false, false, false);
